"""Model for the synthesised Dynamic Care Plan.

The care plan is the orchestration layer's output: one plan reconciled across the
clinical, social-care and family domains. It is regenerated as the underlying
assessment changes, so it carries a ``version``.
"""

from pydantic import BaseModel, Field

from .referral import Recommendation

# Shown on every plan: this reconciles three domains but is decision-support only.
HUMAN_REVIEW_STATEMENT = (
    "This dynamic care plan was generated by an AI orchestration layer by "
    "reconciling clinical, social care and family information. It must be reviewed "
    "and approved by a care coordinator before any action is taken."
)


class CrossDomainFlag(BaseModel):
    """A conflict or gap that spans more than one domain."""

    description: str
    domains: list[str] = Field(default_factory=list)


class CarePlan(BaseModel):
    """A single care plan reconciled across all three domains."""

    patient_name: str
    generated_at: str
    # Increments as the underlying assessment is re-run (makes "dynamic" literal).
    version: int = 1
    discharge_recommendation: str = ""
    summary: str = ""
    # Recommendations come straight from the Social Care Agent, never re-invented.
    recommended_services: list[Recommendation] = Field(default_factory=list)
    clinical_considerations: list[str] = Field(default_factory=list)
    family_considerations: list[str] = Field(default_factory=list)
    cross_domain_flags: list[CrossDomainFlag] = Field(default_factory=list)
    human_review_statement: str = HUMAN_REVIEW_STATEMENT
    text_version: str = ""


class CarePlanRequest(BaseModel):
    """Generate a care plan from an existing case."""

    case_id: str
